CREATE OR REPLACE FORCE EDITIONABLE VIEW "PPPT"."PUESTOSPRANGER" ("IDPUESTO", "INTERPRETACION", "INTERPRETACION1", "INTERPRETACION2", "INTERPRETACION3", "NOMBRE", "NOMBRE1", "NOMBRE2", "NOMBRE3") AS 
  SELECT PuestoInterpretacion.IdPuesto, Interpretacion.Interpretacion, Interpretacion_1.Interpretacion as Interpretacion1, Interpretacion_2.Interpretacion as Interpretacion2, Interpretacion_3.Interpretacion as Interpretacion3, Interpretacion.Nombre, Interpretacion_1.Nombre as Nombre1, Interpretacion_2.Nombre as Nombre2, Interpretacion_3.Nombre as Nombre3 FROM (((PuestoInterpretacion LEFT JOIN Interpretacion ON PuestoInterpretacion.IdInterpretacion1 = Interpretacion.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_1 ON PuestoInterpretacion.IdInterpretacion2 = Interpretacion_1.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_2 ON PuestoInterpretacion.IdInterpretacion3 = Interpretacion_2.IdInterpretacion) INNER JOIN Interpretacion Interpretacion_3 ON PuestoInterpretacion.IdInterpretacion4 = Interpretacion_3.IdInterpretacion WHERE (((PuestoInterpretacion.IdPrueba)=4));
